// =============================================================================
// Cosmos DB Provider — Required fixes for EF Core 9 (separate project)
// =============================================================================
// Apply these changes to your Cosmos DB DbContext and calling code.

using Microsoft.EntityFrameworkCore;

// --- BREAKING CHANGE 1: Discriminator property renamed to "$type" ---
// Existing documents use "Discriminator". You must explicitly preserve it:
//
// modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

// --- BREAKING CHANGE 2: id property no longer contains discriminator ---
// Existing documents have ids like "Product|123". EF Core 9 generates "123".
// Preserve old format so existing documents remain accessible:
//
// modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);

// --- BREAKING CHANGE 3: Sync I/O no longer supported ---
// Synchronous methods (SaveChanges, ToList, First, etc.) now throw.
// You must switch to async equivalents.

// EXAMPLE — Before (breaks in EF Core 9):
//
//   var items = cosmosContext.Products.Where(p => p.Price > 10).ToList();
//   cosmosContext.SaveChanges();
//
// EXAMPLE — After (required fix):
//
//   var items = await cosmosContext.Products.Where(p => p.Price > 10).ToListAsync();
//   await cosmosContext.SaveChangesAsync();

// --- Full OnModelCreating example for existing Cosmos documents ---
class CosmosDbContextFixes : DbContext
{
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve "Discriminator" property name for existing documents
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // Preserve compound id format ("Product|123") for existing documents
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public decimal Price { get; set; }
}

